import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Check, ChevronRight, Clock3, ExternalLink, FileText, FolderArchive, Globe2, History, LayoutDashboard, Link2, LoaderCircle, LockKeyhole, LogOut, Menu, MessageSquare, Monitor, Pause, Play, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Trash2, X } from 'lucide-react';

type Site = { id: string; name: string; url: string; kind: 'own' | 'competitor'; intervalHours: number; maxPages: number; includeSubdomains: boolean; paused: boolean; pageCount: number; versionCount: number; lastCheckedAt?: string; nextCheckAt?: string; ignoreSelectors: string[]; notes?: string };
type Page = { id: string; url: string; title: string; lastCheckedAt?: string; lastStatus?: string; versionCount: number; latestVersionId?: string; latestCheckId?: string; lastChangeAt?: string };
type Version = { id: string; capturedAt: string; title: string; statusCode: number; finalUrl: string; bytes: number; reason: string; warnings: string[]; screenshotUrl: string; htmlUrl: string; text?: string; links?: { url: string; text: string }[] };
type Event = { id: string; kind: string; url: string; siteName: string; createdAt: string; message: string };
type Job = { id: string; siteId: string; pageId?: string; kind: string; status: string; manual: number; paused: number; attempts: number; error?: string; url: string; siteName: string; createdAt: string; startedAt?: string; availableAt: string };
type Dashboard = { version: string; stats: { sites: number; pages: number; versions: number; bytes: number; queued: number; running: number }; events: Event[]; storage: { freeBytes: number; totalBytes: number; minFreeBytes: number }; worker: { available: boolean; message?: string; schedulerEnabled: boolean }; queue: Job[] };
type SiteDetail = { site: Site; pages: Page[]; events: Event[]; jobs: Job[] };
type PageDetail = { page: Page; site: Site; jobs: Job[]; versions: Version[]; checks: { id: string; createdAt: string; status: string; message: string; versionId?: string }[]; notes: string };
type Comparison = { left: Version; right: Version; textDiff: { value: string; added?: boolean; removed?: boolean }[]; changedLinks: { added: { url: string; text: string }[]; removed: { url: string; text: string }[] } };
type Route = { view: 'overview' | 'sites' | 'site' | 'page'; id?: string };
type AuthStatus = { setupRequired: boolean; authenticated: boolean };

async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const response = await fetch(path, { credentials: 'same-origin', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...options.headers } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    if (response.status === 401) window.dispatchEvent(new CustomEvent('session-expired'));
    throw new Error(data.error || 'Non è stato possibile completare la richiesta.');
  }
  return data as T;
}
const post = <T,>(path: string, body = {}) => api<T>(path, { method: 'POST', body: JSON.stringify(body) });
const date = (value?: string, short = false) => value ? new Intl.DateTimeFormat('it-IT', { day: '2-digit', month: 'short', ...(short ? {} : { year: 'numeric' }), hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '—';
const bytes = (value?: number) => { if (value === undefined || value === null || !Number.isFinite(value)) return '—'; if (!value) return '0 B'; const unit = Math.min(Math.floor(Math.log(value) / Math.log(1024)), 4); return `${new Intl.NumberFormat('it-IT', { maximumFractionDigits: unit > 1 ? 1 : 0 }).format(value / 1024 ** unit)} ${['B', 'KB', 'MB', 'GB', 'TB'][unit]}`; };
const host = (url: string) => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return url; } };
const urlPath = (url: string) => { try { const parsed = new URL(url); return parsed.pathname + parsed.search; } catch { return url; } };
const routeFromHash = (): Route => { const [view, id] = window.location.hash.replace(/^#\/?/, '').split('/'); return ['sites', 'site', 'page'].includes(view) ? { view: view as Route['view'], id } : { view: 'overview' }; };
const go = (view: Route['view'], id?: string) => { window.location.hash = `/${view}${id ? `/${id}` : ''}`; };
const statusLabel = (status?: string) => ({ ok: 'Archiviata', unavailable: 'Da verificare', recovered: 'Tornata online', changed: 'Modificata', new: 'Prima copia', captured: 'Archiviata', unchanged: 'Invariata', error: 'Errore', failed: 'Errore', missing: 'Non raggiungibile', disappeared: 'Non raggiungibile', removed: 'Non raggiungibile', restored: 'Tornata online', returned: 'Versione ritornata', cancelled: 'Interrotto', queued: 'In attesa', running: 'In corso', succeeded: 'Completato', success: 'Completato', blocked: 'Accesso bloccato', discovered: 'Pagina scoperta', discovery: 'Ricerca pagine', capture: 'Acquisizione' }[status || ''] || (status ? 'Controllata' : 'Da acquisire'));
const isErrorStatus = (status?: string) => !!status && ['error', 'failed', 'unavailable', 'missing', 'disappeared', 'removed', 'blocked'].includes(status);

function Spinner({ label = 'Caricamento' }: { label?: string }) { return <div className="loading" role="status"><LoaderCircle className="spin" size={22} /><span>{label}…</span></div>; }
type Action = (fn: () => Promise<unknown>, message: string) => Promise<void>;

function ScanButton({ siteId, pageId, running, perform, compact = false }: { siteId: string; pageId?: string; running: boolean; perform: Action; compact?: boolean }) {
  const [busy, setBusy] = useState(false);
  return <button className={`button ${compact ? 'secondary compact' : 'primary'}`} disabled={busy} onClick={async () => {
    setBusy(true);
    try { await perform(() => post(pageId ? `/api/pages/${pageId}/scan` : `/api/sites/${siteId}/scan`, { force: true, discover: !pageId }), 'Controllo manuale prioritario richiesto. Lo stato si aggiorna qui sotto.'); }
    finally { setBusy(false); }
  }} title={running ? 'Interrompe il tentativo corrente e avvia un nuovo controllo.' : 'Scarica di nuovo la pagina anche se il monitoraggio è in pausa. Conserva una nuova versione quando rileva modifiche.'}>
    {busy ? <LoaderCircle className="spin" size={17} /> : <RefreshCw size={17} />}{busy ? 'Richiesta in corso…' : running ? 'Riavvia controllo' : compact ? 'Scarica ora' : 'Controlla e scarica ora'}
  </button>;
}

function AcquisitionStatus({ jobs, paused, error }: { jobs: Job[]; paused: boolean; error?: string }) {
  const running = jobs.find(job => job.status === 'running');
  const queued = jobs.filter(job => job.status === 'queued');
  const next = queued.find(job => !job.paused || job.manual);
  const seconds = running?.startedAt ? Math.max(0, Math.floor((Date.now() - Date.parse(running.startedAt)) / 1000)) : 0;
  return <section className="acquisition-status" aria-label="Stato acquisizioni" aria-live="polite">
    <div><strong>{running ? `${statusLabel(running.kind)} in corso · ${seconds} secondi` : next ? Date.parse(next.availableAt) > Date.now() ? `Nuovo tentativo previsto: ${date(next.availableAt, true)}` : 'Controllo pronto, in attesa del motore' : paused ? 'Monitoraggio automatico in pausa' : 'Nessuna acquisizione in corso'}</strong>
      {running && <p>{urlPath(running.url)} · tentativo {running.attempts}/3. Il tempo massimo per un lavoro è 3 minuti.</p>}
      {!!queued.length && <p>{queued.length}{queued.length >= 100 ? '+' : ''} {queued.length === 1 ? 'controllo in attesa' : 'controlli in attesa'}. I controlli manuali hanno la precedenza.</p>}
      <p>{paused ? 'Il comando manuale funziona anche in pausa e non riattiva la pianificazione.' : '«Controlla e scarica ora» avvia una nuova visita. Se il contenuto è invariato, viene registrato il controllo senza duplicare la versione.'}{running && ' «Riavvia controllo» interrompe il tentativo corrente.'}</p>
    </div>
    {(next?.error || error) && <div className="acquisition-error"><strong>Ultimo errore registrato</strong><p>{next?.error || error}</p></div>}
  </section>;
}

function DeleteSiteModal({ site, close, deleted }: { site: Site; close: () => void; deleted: (pendingFiles: number) => Promise<void> }) {
  const [confirmed, setConfirmed] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  return <Modal title="Elimina sito dall’archivio" subtitle={site.name} close={() => { if (!busy) close(); }}>
    <form onSubmit={async event => {
      event.preventDefault(); if (!confirmed || busy) return; setBusy(true); setError('');
      try {
        const result = await api<{ pendingFiles: number }>(`/api/sites/${site.id}`, { method: 'DELETE', body: JSON.stringify({ confirmSiteId: site.id }) });
        await deleted(result.pendingFiles);
      } catch (error) { setError((error as Error).message); } finally { setBusy(false); }
    }}><div className="modal-body">
      <p>Verranno eliminati <strong>{site.pageCount} {site.pageCount === 1 ? 'pagina' : 'pagine'}</strong>, <strong>{site.versionCount} {site.versionCount === 1 ? 'versione' : 'versioni'}</strong>, note e cronologia di questo sito. I controlli in corso e quelli programmati saranno annullati.</p>
      <p>I file usati anche da altri siti verranno conservati. Questa operazione non può essere annullata dall’app; per recuperare le copie serve un backup precedente.</p>
      <a className="text-button" href="/api/export" download><ArrowDownToLine size={16} /> Scarica prima un backup dell’archivio</a>
      <label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} disabled={busy} /><span>Confermo l’eliminazione del sito e delle sue copie archiviate.</span></label>
      {error && <div className="notice error" role="alert">{error}</div>}
    </div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>Annulla</button><button className="button danger" disabled={!confirmed || busy}>{busy ? <LoaderCircle className="spin" size={17} /> : <Trash2 size={17} />}{busy ? 'Eliminazione…' : 'Elimina definitivamente'}</button></div></form>
  </Modal>;
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'amber' }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Empty({ icon, title, children, action }: { icon: ReactNode; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{children}</p>{action}</div>; }

export default function App() {
  const [auth, setAuth] = useState<AuthStatus | null>(null);
  const [initialError, setInitialError] = useState('');
  useEffect(() => {
    const load = () => api<AuthStatus>('/api/auth/status').then(setAuth).catch(error => setInitialError(error.message));
    load(); window.addEventListener('session-expired', load); return () => window.removeEventListener('session-expired', load);
  }, []);
  if (!auth) return <main className="startup"><Brand />{initialError ? <div className="notice error">{initialError}<button className="text-button" onClick={() => window.location.reload()}>Riprova</button></div> : <Spinner label="Apertura dell’archivio" />}</main>;
  if (!auth.authenticated) return <AuthScreen setup={auth.setupRequired} onSuccess={() => setAuth({ setupRequired: false, authenticated: true })} />;
  return <Workspace onLogout={async () => { await post('/api/auth/logout'); setAuth({ setupRequired: false, authenticated: false }); }} />;
}

function Brand() { return <div className="brand"><div className="brand-icon"><History size={24} strokeWidth={1.8} /></div><div><strong>Landing Archive</strong><span>La memoria dei tuoi siti</span></div></div>; }

function AuthScreen({ setup, onSuccess }: { setup: boolean; onSuccess: () => void }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); if (setup && password !== confirm) { setError('Le due password non coincidono.'); return; } setBusy(true); setError(''); try { await post(setup ? '/api/auth/setup' : '/api/auth/login', { username, password }); onSuccess(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }
  return <main className="auth-layout"><section className="auth-story"><Brand /><div><span className="eyebrow light">IL TUO OSSERVATORIO WEB</span><h1>Le pagine cambiano.<br />La loro storia resta.</h1><p>Conserva le landing, ritrova le offerte passate e osserva come si evolvono i siti che segui.</p><div className="auth-steps"><span><Globe2 size={18} /> Segui i siti</span><span><FolderArchive size={18} /> Conserva le versioni</span><span><History size={18} /> Esplora la storia</span></div></div><span className="auth-local"><ShieldCheck size={17} /> Il tuo archivio rimane sul tuo dispositivo.</span></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><div className="auth-lock"><LockKeyhole size={23} /></div><span className="eyebrow">{setup ? 'BENVENUTO NEL TUO ARCHIVIO' : 'IL TUO SPAZIO PRIVATO'}</span><h2>{setup ? 'Prepariamo il tuo accesso.' : 'Bentornato.'}</h2><p>{setup ? 'Crea un account locale per proteggere siti, catture e annotazioni.' : 'Accedi per consultare la storia dei siti che segui.'}</p><label>Nome utente<input autoFocus autoComplete="username" required minLength={3} maxLength={40} value={username} onChange={event => setUsername(event.target.value)} /></label><label>Password<input type="password" autoComplete={setup ? 'new-password' : 'current-password'} required minLength={setup ? 12 : undefined} value={password} onChange={event => setPassword(event.target.value)} />{setup && <small>Almeno 12 caratteri. Conservala in un posto sicuro.</small>}</label>{setup && <label>Ripeti la password<input type="password" autoComplete="new-password" required value={confirm} onChange={event => setConfirm(event.target.value)} /></label>}{error && <div className="notice error" role="alert">{error}</div>}<button className="button primary full" disabled={busy}>{busy ? <LoaderCircle size={18} className="spin" /> : <ArrowRight size={18} />}{setup ? 'Crea il tuo archivio' : 'Accedi'}</button></form></section></main>;
}

function Workspace({ onLogout }: { onLogout: () => Promise<void> }) {
  const [route, setRoute] = useState<Route>(routeFromHash); const [sites, setSites] = useState<Site[]>([]); const [dashboard, setDashboard] = useState<Dashboard | null>(null); const [detail, setDetail] = useState<SiteDetail | PageDetail | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [toast, setToast] = useState(''); const [editingSite, setEditingSite] = useState<Site | 'new' | null>(null); const [deletingSite, setDeletingSite] = useState<Site | null>(null); const [mobileNav, setMobileNav] = useState(false); const [search, setSearch] = useState(''); const [results, setResults] = useState<{ id: string; url: string; title: string; siteName: string }[] | null>(null);
  const requestId = useRef(0); const currentRoute = useRef(route); currentRoute.current = route;
  const load = useCallback(async (silent = false) => {
    const id = ++requestId.current;
    if (!silent) setLoading(true);
    try {
      const [siteData, dashboardData, detailData] = await Promise.all([api<{ sites: Site[] }>('/api/sites'), api<Dashboard>('/api/dashboard'), route.id && (route.view === 'site' || route.view === 'page') ? api<SiteDetail | PageDetail>(`/api/${route.view === 'site' ? 'sites' : 'pages'}/${route.id}`) : Promise.resolve(null)]);
      if (id !== requestId.current) return;
      setSites(siteData.sites); setDashboard(dashboardData); setDetail(detailData); setError('');
    } catch (error) { if (id === requestId.current) setError((error as Error).message); }
    finally { if (id === requestId.current) setLoading(false); }
  }, [route.view, route.id]);
  useEffect(() => { const handler = () => { setRoute(routeFromHash()); setDetail(null); setMobileNav(false); setSearch(''); window.scrollTo(0, 0); }; window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, []);
  useEffect(() => { load(); }, [load]);
  const activeJobs = (dashboard?.stats.queued || 0) + (dashboard?.stats.running || 0);
  useEffect(() => { const timer = window.setInterval(() => { if (!document.hidden) load(true); }, activeJobs ? 4000 : 30000); return () => clearInterval(timer); }, [load, activeJobs]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 5500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { if (!search.trim()) { setResults(null); return; } let cancelled = false; const timer = window.setTimeout(() => { api<{ pages: NonNullable<typeof results> }>(`/api/search?q=${encodeURIComponent(search.trim())}`).then(data => { if (!cancelled) setResults(data.pages); }).catch(() => { if (!cancelled) setResults([]); }); }, 250); return () => { cancelled = true; clearTimeout(timer); }; }, [search]);
  const notify = (message: string) => setToast(message);
  const perform = async (fn: () => Promise<unknown>, message: string) => { try { await fn(); notify(message); await load(true); } catch (error) { setError((error as Error).message); } };
  const selectedSite = detail?.site || null;
  const deleted = async (pendingFiles: number) => {
    ++requestId.current; setDeletingSite(null); setDetail(null); setError(''); setSearch(''); setResults(null);
    notify(pendingFiles ? 'Sito eliminato. Alcuni file non sono stati rimossi dal disco: controlla i permessi del volume dati.' : 'Sito e archivio eliminati. I file condivisi con altri siti sono conservati.');
    if (currentRoute.current.view === 'sites') await load(true); else go('sites');
  };
  return <div className="app-shell"><aside className={`sidebar ${mobileNav ? 'open' : ''}`}><a className="brand-link" href="#/overview"><Brand /></a><div className="sidebar-label">IL TUO ARCHIVIO</div><nav aria-label="Navigazione principale"><a href="#/overview" className={`nav-item ${route.view === 'overview' ? 'active' : ''}`}><LayoutDashboard size={19} /> Panoramica</a><a href="#/sites" className={`nav-item ${route.view !== 'overview' ? 'active' : ''}`}><Globe2 size={19} /> Siti monitorati <span>{sites.length}</span></a></nav><div className="sidebar-label sites-label">SITI RECENTI <button className="icon-button" aria-label="Aggiungi sito" onClick={() => setEditingSite('new')}><Plus size={17} /></button></div><div className="sidebar-sites">{sites.slice(0, 8).map(site => <a key={site.id} href={`#/site/${site.id}`} className={`sidebar-site ${selectedSite?.id === site.id ? 'selected' : ''}`}><span className={`site-dot ${site.paused ? 'paused' : ''}`} /><span>{site.name}</span>{site.kind === 'own' && <span className="own-dot" title="Un tuo sito" />}</a>)}{!sites.length && <p className="sidebar-hint">I siti che aggiungi compariranno qui.</p>}</div><div className="sidebar-bottom"><div className="local-status"><ShieldCheck size={19} /><div><strong>Archivio locale</strong><span>I tuoi dati, sul tuo dispositivo</span></div></div><a className="nav-item subdued" href="/api/export" download><ArrowDownToLine size={18} /> Esporta archivio</a><button className="nav-item subdued" onClick={() => perform(onLogout, '')}><LogOut size={18} /> Esci</button><div className="sidebar-version">LANDING ARCHIVE <span>v{dashboard?.version || "…"}</span></div></div></aside>{mobileNav && <button className="nav-scrim" aria-label="Chiudi navigazione" onClick={() => setMobileNav(false)} />}
    <div className="workspace"><header className="topbar"><button className="icon-button mobile-toggle" aria-label="Apri navigazione" onClick={() => setMobileNav(!mobileNav)}><Menu size={23} /></button><div className="breadcrumb"><span>Archivio</span><ChevronRight size={14} /><strong>{route.view === 'overview' ? 'Panoramica' : route.view === 'sites' ? 'Siti monitorati' : selectedSite?.name || 'Dettaglio'}</strong></div><div className="global-search"><Search size={17} /><input aria-label="Cerca pagine nell’archivio" placeholder="Cerca nell’archivio…" value={search} onChange={event => setSearch(event.target.value)} />{search && <button className="icon-button" aria-label="Cancella ricerca" onClick={() => setSearch('')}><X size={15} /></button>}{results !== null && <div className="search-results">{results.length ? results.map(result => <button key={result.id} onClick={() => { go('page', result.id); setSearch(''); }}><span>{result.title || urlPath(result.url)}</span><small>{result.siteName} · {host(result.url)}</small></button>) : <p>Nessuna pagina trovata.</p>}</div>}</div><div className={`worker-status ${dashboard?.worker.available ? '' : 'offline'}`}><span />{dashboard?.worker.available ? dashboard?.stats.running ? 'Acquisizioni in corso' : activeJobs ? 'Controlli in attesa' : sites.some(site => !site.paused) ? 'Monitoraggio attivo' : 'Archivio pronto' : 'Acquisizioni non disponibili'}</div></header>
    <main className="main-content">{error && <div className="notice error" role="alert"><span>{error}</span><button className="text-button" onClick={() => load()}>Riprova</button><button className="icon-button" aria-label="Chiudi errore" onClick={() => setError('')}><X size={17} /></button></div>}{dashboard && !dashboard.worker.available && <div className="notice amber"><Clock3 size={18} /><span>{dashboard.worker.message || "Il servizio di acquisizione non è attivo. Controlla lo stato dell’app in Umbrel."}</span></div>}{dashboard && !dashboard.worker.schedulerEnabled && <div className="notice amber">I controlli automatici sono disattivati. Puoi usare «Controlla e scarica ora» per una visita manuale.</div>}{dashboard && dashboard.storage.freeBytes < dashboard.storage.minFreeBytes && <div className="notice amber"><FolderArchive size={18} /><span>Lo spazio libero è sotto la soglia di sicurezza. Le nuove acquisizioni sono sospese; le versioni esistenti restano disponibili.</span></div>}
    {loading ? <Spinner label="Caricamento dell’archivio" /> : route.view === 'overview' && dashboard ? <Overview data={dashboard} sites={sites} addSite={() => setEditingSite('new')} /> : route.view === 'sites' ? <SitesView sites={sites} addSite={() => setEditingSite('new')} remove={setDeletingSite} perform={perform} jobs={dashboard?.queue || []} /> : route.view === 'site' && detail && !('page' in detail) ? <SiteView detail={detail} edit={() => setEditingSite(detail.site)} remove={() => setDeletingSite(detail.site)} perform={perform} refresh={() => load(true)} notify={notify} /> : route.view === 'page' && detail && 'page' in detail ? <PageView detail={detail} perform={perform} /> : <Empty icon={<Globe2 size={30} />} title="Pagina non disponibile" action={<a className="button secondary" href="#/overview">Torna alla panoramica</a>}>Il contenuto richiesto non è disponibile nell’archivio.</Empty>}
    </main><footer className="workspace-footer"><span><LockKeyhole size={13} /> Le catture restano nel tuo archivio locale</span><a href="/api/source" download>Codice sorgente · AGPL-3.0</a></footer></div>
    {deletingSite && <DeleteSiteModal site={deletingSite} close={() => setDeletingSite(null)} deleted={deleted} />}{editingSite && <SiteModal site={editingSite === 'new' ? undefined : editingSite} close={() => setEditingSite(null)} saved={async () => { setEditingSite(null); notify(editingSite === 'new' ? 'Sito aggiunto. La prima acquisizione è in coda.' : 'Impostazioni del sito salvate.'); await load(true); }} />}{toast && <div className="toast" role="status"><Check size={18} /><span>{toast}</span><button className="icon-button" aria-label="Chiudi notifica" onClick={() => setToast('')}><X size={16} /></button></div>}
  </div>;
}

function Overview({ data, sites, addSite }: { data: Dashboard; sites: Site[]; addSite: () => void }) {
  return <><div className="page-heading"><div><span className="eyebrow">OGNI CAMBIAMENTO, AL SUO POSTO</span><h1>Il web cambia. Tu tieni il filo.</h1><p>La storia dei tuoi siti e dei competitor, raccolta giorno dopo giorno.</p></div><button className="button primary" onClick={addSite}><Plus size={18} /> Aggiungi sito</button></div><div className="stats-grid">{([{ label: 'Siti monitorati', value: data.stats.sites, icon: <Globe2 size={20} />, sub: `${sites.filter(site => site.kind === 'own').length} tuoi · ${sites.filter(site => site.kind === 'competitor').length} competitor` }, { label: 'Pagine scoperte', value: data.stats.pages, icon: <FileText size={20} />, sub: 'Landing e pagine nell’archivio' }, { label: 'Versioni conservate', value: data.stats.versions, icon: <History size={20} />, sub: 'Copie salvate nel tempo' }, { label: 'Spazio archivio', value: bytes(data.stats.bytes), icon: <FolderArchive size={20} />, sub: `${bytes(data.storage.freeBytes)} liberi sul disco` }]).map(stat => <div className="stat-card" key={stat.label}><div><span>{stat.label}</span>{stat.icon}</div><strong>{stat.value}</strong><small>{stat.sub}</small></div>)}</div>
    {!sites.length ? <section className="welcome-panel"><div className="welcome-illustration"><div className="illustration-page back"><span /><span /><span /></div><div className="illustration-page front"><div /><span /><span /><span /><History size={34} /></div></div><div><span className="eyebrow">LA PRIMA PAGINA DELLA TUA STORIA</span><h2>Da quale sito cominciamo?</h2><p>Aggiungi un dominio o una landing. Conserveremo una prima copia e controlleremo i cambiamenti alla frequenza che scegli.</p><button className="button primary" onClick={addSite}><Plus size={18} /> Aggiungi il primo sito</button></div></section> : <div className="overview-columns"><section className="panel"><div className="panel-heading"><div><h2>I siti che segui</h2><p>Un punto di partenza per ogni storia.</p></div><a className="text-button" href="#/sites">Vedi tutti <ArrowRight size={16} /></a></div><div className="site-list">{sites.slice(0, 5).map(site => <SiteRow key={site.id} site={site} />)}</div></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>Ultimi movimenti</h2><p>Nuove pagine, versioni e controlli.</p></div><span className="small-icon"><History size={19} /></span></div><EventList events={data.events.slice(0, 8)} /></section></div>}
    {!!data.queue.length && <section className="panel queue-panel"><div className="panel-heading"><div><h2>Acquisizioni in coda</h2><p>{data.stats.running} in corso · {data.stats.queued} in attesa</p></div><LoaderCircle size={19} className={data.stats.running ? 'spin' : ''} /></div><div className="queue-list">{data.queue.slice(0, 8).map(job => <div key={job.id}><span className={`queue-dot ${job.status === 'running' ? 'running' : ''}`} /><div><strong>{job.siteName || host(job.url)}</strong><small title={job.url}>{job.url}</small></div><span className="muted job-kind">{statusLabel(job.kind)}</span><Badge tone={job.status === 'running' ? 'green' : 'neutral'}>{statusLabel(job.status)}</Badge></div>)}</div></section>}
    <section className="insight-strip"><div className="insight-icon"><Sparkles size={21} /></div><p><strong>Una landing può sparire. La tua copia rimane.</strong><span>Aggiungi anche gli indirizzi trovati negli annunci e nelle newsletter: le pagine senza collegamenti pubblici possono sfuggire alla scansione.</span></p></section></>;
}

function SiteRow({ site }: { site: Site }) { return <a className="site-row" href={`#/site/${site.id}`}><div className={`site-avatar ${site.kind === 'own' ? 'own' : ''}`}>{site.name.slice(0, 1).toUpperCase()}</div><div className="site-row-name"><strong>{site.name}</strong><span>{host(site.url)}</span></div><div className="site-row-count"><strong>{site.pageCount || 0} pagine</strong><span>{site.versionCount || 0} versioni</span></div><Badge tone={site.paused ? 'neutral' : 'green'}>{site.paused ? 'In pausa' : `Ogni ${site.intervalHours} h`}</Badge><ChevronRight size={17} className="muted" /></a>; }

function EventList({ events }: { events: Event[] }) { return events.length ? <div className="event-list">{events.map(event => <div className="event-row" key={event.id}><div className={`event-marker ${isErrorStatus(event.kind) ? 'warning' : ''}`}>{isErrorStatus(event.kind) ? <Clock3 size={14} /> : event.kind === 'discovered' || event.kind === 'new' ? <Plus size={14} /> : <History size={14} />}</div><div><div className="event-top"><strong>{event.siteName || host(event.url)}</strong><time>{date(event.createdAt, true)}</time></div><p>{event.message || statusLabel(event.kind)}</p>{event.url && <small title={event.url}>{urlPath(event.url)}</small>}</div></div>)}</div> : <div className="activity-empty"><Clock3 size={26} /><p>La storia comincia con il primo controllo.</p><span>Qui compariranno i movimenti dei tuoi siti.</span></div>; }

function SitesView({ sites, addSite, remove, perform, jobs }: { sites: Site[]; addSite: () => void; remove: (site: Site) => void; perform: Action; jobs: Job[] }) {
  const [filter, setFilter] = useState('all'); const [query, setQuery] = useState(''); const filtered = sites.filter(site => (filter === 'all' || site.kind === filter) && `${site.name} ${site.url}`.toLowerCase().includes(query.toLowerCase()));
  return <><div className="page-heading"><div><span className="eyebrow">IL TUO OSSERVATORIO</span><h1>Siti monitorati</h1><p>Segui i tuoi progetti e osserva come si muovono i competitor.</p></div><button className="button primary" onClick={addSite}><Plus size={18} /> Aggiungi sito</button></div><div className="list-toolbar"><div className="tabs">{[{ key: 'all', label: 'Tutti i siti' }, { key: 'own', label: 'I miei siti' }, { key: 'competitor', label: 'Competitor' }].map(tab => <button key={tab.key} className={filter === tab.key ? 'selected' : ''} onClick={() => setFilter(tab.key)}>{tab.label} <span>{sites.filter(site => tab.key === 'all' || site.kind === tab.key).length}</span></button>)}</div><div className="input-search"><Search size={16} /><input aria-label="Filtra siti" placeholder="Filtra per nome o dominio" value={query} onChange={event => setQuery(event.target.value)} /></div></div>{filtered.length ? <div className="site-cards">{filtered.map(site => <article className="site-card" key={site.id}><a className="site-card-link" href={`#/site/${site.id}`}><div className="site-card-top"><div className={`site-avatar ${site.kind === 'own' ? 'own' : ''}`}>{site.name.slice(0, 1).toUpperCase()}</div><Badge>{site.kind === 'own' ? 'Il mio sito' : 'Competitor'}</Badge><ArrowUpRight size={19} /></div><h2>{site.name}</h2><p className="domain">{host(site.url)}</p><div className="site-card-numbers"><div><strong>{site.pageCount || 0}</strong><span>Pagine</span></div><div><strong>{site.versionCount || 0}</strong><span>Versioni</span></div></div><div className="site-card-footer"><span><span className={`site-dot ${site.paused ? 'paused' : ''}`} />{site.paused ? 'Monitoraggio in pausa' : `Controllo ogni ${site.intervalHours} h`}</span><small>Ultimo: {date(site.lastCheckedAt, true)}</small></div></a><div className="site-card-actions"><ScanButton siteId={site.id} running={jobs.some(job => job.siteId === site.id && job.status === "running")} perform={perform} compact /><button className="button danger-outline compact" onClick={() => remove(site)} aria-label={`Elimina ${site.name}`}><Trash2 size={15} /> Elimina</button></div></article>)}</div> : <div className="panel"><Empty icon={<Globe2 size={30} />} title={sites.length ? 'Nessun sito corrispondente' : 'Il tuo archivio parte da un indirizzo'} action={!sites.length && <button className="button primary" onClick={addSite}><Plus size={17} /> Aggiungi sito</button>}>{sites.length ? 'Prova a cambiare filtro o ricerca.' : 'Aggiungi il primo sito per iniziare a conservarne la storia.'}</Empty></div>}</>;
}

function SiteView({ detail, edit, remove, perform, refresh, notify }: { detail: SiteDetail; edit: () => void; remove: () => void; perform: (fn: () => Promise<unknown>, message: string) => Promise<void>; refresh: () => Promise<void>; notify: (message: string) => void }) {
  const { site, pages } = detail; const [filter, setFilter] = useState(''); const [addingPage, setAddingPage] = useState(false);
  return <><a className="back-link" href="#/sites"><ArrowLeft size={15} /> Tutti i siti</a><div className="page-heading site-heading"><div><div className="heading-badges"><Badge tone="green">{site.kind === 'own' ? 'Il mio sito' : 'Competitor'}</Badge>{site.paused && <Badge>In pausa</Badge>}</div><h1>{site.name}</h1><a className="external-link" href={site.url} target="_blank" rel="noreferrer">{site.url}<ExternalLink size={13} /></a></div><div className="button-group"><button className="button secondary" onClick={edit}><Settings2 size={17} /> Impostazioni</button><ScanButton siteId={site.id} running={detail.jobs.some(job => job.status === "running")} perform={perform} /><button className="button danger-outline" onClick={remove}><Trash2 size={17} /> Elimina sito</button></div></div><div className="site-summary"><span><FileText size={17} /><strong>{pages.length}</strong> pagine</span><span><History size={17} /><strong>{site.versionCount || 0}</strong> versioni</span><span><Clock3 size={17} /> Ogni {site.intervalHours} ore</span><span className="next-check">{site.paused ? 'Pianificazione sospesa' : `Prossimo controllo: ${date(site.nextCheckAt, true)}`}</span></div><AcquisitionStatus jobs={detail.jobs} paused={site.paused} error={detail.events.find(event => isErrorStatus(event.kind))?.message} /><section className="panel pages-panel"><div className="panel-heading"><div><h2>Le pagine del sito</h2><p>Apri una pagina per esplorarne le versioni.</p></div><button className="button secondary compact" onClick={() => setAddingPage(true)}><Plus size={16} /> Aggiungi URL</button></div>{pages.length > 0 && <div className="table-toolbar"><div className="input-search"><Search size={16} /><input aria-label="Filtra pagine" placeholder="Cerca una landing o un titolo" value={filter} onChange={event => setFilter(event.target.value)} /></div><span className="muted">Limite scoperta: {site.maxPages} pagine</span></div>}{pages.length ? <div className="table-scroll"><table className="pages-table"><thead><tr><th>Pagina</th><th>Ultimo controllo</th><th>Stato</th><th>Versioni</th><th><span className="sr-only">Apri</span></th></tr></thead><tbody>{pages.filter(page => `${page.url} ${page.title}`.toLowerCase().includes(filter.toLowerCase())).map(page => <tr key={page.id}><td><a href={`#/page/${page.id}`}><strong>{page.title || urlPath(page.url)}</strong><small title={page.url}>{urlPath(page.url)}</small></a></td><td className="nowrap">{date(page.lastCheckedAt, true)}</td><td><Badge tone={isErrorStatus(page.lastStatus) ? 'amber' : page.versionCount ? 'green' : 'neutral'}>{statusLabel(page.lastStatus)}</Badge></td><td><span className="version-count"><History size={14} />{page.versionCount || 0}</span></td><td><a className="icon-button" href={`#/page/${page.id}`} aria-label={`Apri ${page.title || page.url}`}><ArrowRight size={17} /></a></td></tr>)}</tbody></table>{!pages.some(page => `${page.url} ${page.title}`.toLowerCase().includes(filter.toLowerCase())) && <p className="no-results">Nessuna pagina corrisponde alla ricerca.</p>}</div> : <Empty icon={<Search size={29} />} title="Alla ricerca delle prime pagine">La scansione cercherà pagine collegate e sitemap. Puoi aggiungere manualmente una landing in qualsiasi momento.</Empty>}</section><div className="site-lower-grid"><section className="panel"><div className="panel-heading"><div><h2>Attività del sito</h2><p>La cronologia dei controlli e delle scoperte.</p></div></div><EventList events={detail.events.slice(0, 8)} /></section><section className="panel site-guidance"><Link2 size={24} /><h2>Hai trovato una nuova landing?</h2><p>Gli indirizzi presenti solo in annunci, email o aree riservate possono sfuggire alla ricerca automatica. Aggiungili qui per seguirne la storia.</p><button className="button secondary" onClick={() => setAddingPage(true)}><Plus size={16} /> Aggiungi un indirizzo</button><div className="site-guidance-note"><ShieldCheck size={17} /><span>Le versioni precedenti rimangono disponibili anche quando una pagina cambia o scompare.</span></div></section></div>{addingPage && <AddPageModal site={site} close={() => setAddingPage(false)} saved={async () => { setAddingPage(false); notify('Pagina aggiunta. La prima acquisizione è in coda.'); await refresh(); }} />}</>;
}

function PageView({ detail, perform }: { detail: PageDetail; perform: (fn: () => Promise<unknown>, message: string) => Promise<void> }) {
  const { page, site } = detail; const versions = [...detail.versions].sort((a, b) => new Date(b.capturedAt).getTime() - new Date(a.capturedAt).getTime());
  const [selectedId, setSelectedId] = useState(versions[0]?.id || ''); const [mode, setMode] = useState<'preview' | 'compare' | 'checks'>('preview'); const [notes, setNotes] = useState(detail.notes || ''); const [savingNotes, setSavingNotes] = useState(false); const [imageError, setImageError] = useState(false);
  useEffect(() => { setSelectedId(versions[0]?.id || ''); setMode('preview'); setNotes(detail.notes || ''); }, [page.id]);
  useEffect(() => { if (!selectedId && versions[0]) setSelectedId(versions[0].id); }, [versions, selectedId]);
  useEffect(() => setImageError(false), [selectedId]);
  const selected = versions.find(version => version.id === selectedId) || versions[0];
  return <><a className="back-link" href={`#/site/${site.id}`}><ArrowLeft size={15} /> {site.name}</a><div className="page-heading detail-heading"><div><span className="eyebrow">STORIA DELLA PAGINA</span><h1>{page.title || urlPath(page.url)}</h1><a className="external-link" href={page.url} target="_blank" rel="noreferrer">{page.url}<ExternalLink size={13} /></a></div><ScanButton siteId={site.id} pageId={page.id} running={detail.jobs.some(job => job.status === "running")} perform={perform} /></div><AcquisitionStatus jobs={detail.jobs} paused={site.paused} error={detail.checks[0] && isErrorStatus(detail.checks[0].status) ? detail.checks[0].message : undefined} /><div className="page-detail-tabs"><div className="tabs"><button className={mode === 'preview' ? 'selected' : ''} onClick={() => setMode('preview')}><Monitor size={16} /> Versioni <span>{versions.length}</span></button><button className={mode === 'compare' ? 'selected' : ''} disabled={versions.length < 2} title={versions.length < 2 ? 'Servono almeno due versioni per il confronto' : undefined} onClick={() => setMode('compare')}><History size={16} /> Confronta</button><button className={mode === 'checks' ? 'selected' : ''} onClick={() => setMode('checks')}><Clock3 size={16} /> Controlli <span>{detail.checks.length}</span></button></div><span className="muted">Ultimo controllo: {date(page.lastCheckedAt, true)}</span></div>
  {mode === 'preview' && (versions.length ? <div className="timeline-layout"><aside className="panel timeline-panel"><div className="timeline-heading"><h2>Linea del tempo</h2><p>Ogni versione racconta un passaggio.</p></div><div className="timeline-list">{versions.map((version, index) => <button className={`timeline-item ${selected?.id === version.id ? 'selected' : ''}`} key={version.id} onClick={() => setSelectedId(version.id)}><span className="timeline-node" /><div><time>{date(version.capturedAt)}</time><strong>{index === versions.length - 1 ? 'Prima acquisizione' : version.reason || 'Nuova versione'}</strong><small>{bytes(version.bytes)}{version.warnings?.length ? ' · Con avvisi' : ''}</small></div>{selected?.id === version.id && <ChevronRight size={16} />}</button>)}</div><div className="timeline-footnote">Anche il ritorno a una vecchia versione resta nella storia.</div></aside><section className="panel capture-panel"><div className="capture-toolbar"><div><span className="capture-browser-dots"><i /><i /><i /></span><span title={selected?.finalUrl}>{host(selected?.finalUrl || page.url)}{urlPath(selected?.finalUrl || page.url)}</span></div><a className="button secondary compact" href={selected?.htmlUrl} download><ArrowDownToLine size={15} /> Scarica HTML</a></div><div className="capture-meta"><span><Monitor size={15} /> Vista desktop</span><time>{date(selected?.capturedAt)}</time><Badge tone={selected?.statusCode && selected.statusCode >= 400 ? 'amber' : 'green'}>{selected?.statusCode ? `HTTP ${selected.statusCode}` : 'Acquisita'}</Badge></div>{selected?.warnings?.length > 0 && <div className="capture-warnings"><strong>Questa acquisizione richiede attenzione</strong>{selected.warnings.map((warning, index) => <p key={index}>{warning}</p>)}</div>}<div className="screenshot-view">{imageError || !selected?.screenshotUrl ? <Empty icon={<Monitor size={28} />} title="Anteprima non disponibile">La copia HTML, se acquisita, è scaricabile dal pulsante in alto.</Empty> : <a href={selected.screenshotUrl} target="_blank" rel="noreferrer" title="Apri lo screenshot completo"><img key={selected.id} src={selected.screenshotUrl} alt={`Screenshot di ${page.title || host(page.url)} acquisito il ${date(selected.capturedAt)}`} onError={() => setImageError(true)} /></a>}</div><div className="capture-footer"><ShieldCheck size={14} /> Anteprima statica della pagina archiviata. Nessuno script del sito viene eseguito qui.</div></section></div> : <section className="panel"><Empty icon={<History size={31} />} title={detail.checks.some(check => isErrorStatus(check.status)) ? "La prima acquisizione non è riuscita" : "Nessuna versione archiviata"} action={<ScanButton siteId={site.id} pageId={page.id} running={detail.jobs.some(job => job.status === "running")} perform={perform} />}>Quando l’acquisizione sarà completata, qui potrai esplorare la pagina e tutte le sue versioni successive.</Empty></section>)}
  {mode === 'compare' && <CompareView versions={versions} />}{mode === 'checks' && <section className="panel checks-panel"><div className="panel-heading"><div><h2>Ultimi controlli</h2><p>Ultimi 1.000 controlli. Un controllo invariato resta registrato senza creare un’altra copia.</p></div></div>{detail.checks.length ? <div className="table-scroll"><table className="checks-table"><thead><tr><th>Data</th><th>Esito</th><th>Dettaglio</th><th /></tr></thead><tbody>{detail.checks.map(check => <tr key={check.id}><td className="nowrap">{date(check.createdAt)}</td><td><Badge tone={isErrorStatus(check.status) ? 'amber' : check.status === 'unchanged' ? 'neutral' : 'green'}>{statusLabel(check.status)}</Badge></td><td>{check.message}</td><td>{check.versionId && <button className="text-button" onClick={() => { setSelectedId(check.versionId!); setMode('preview'); }}>Apri versione <ArrowRight size={14} /></button>}</td></tr>)}</tbody></table></div> : <Empty icon={<Clock3 size={28} />} title="Nessun controllo completato">I controlli compariranno qui, compresi quelli senza modifiche.</Empty>}</section>}
  <section className="panel notes-panel"><div className="notes-heading"><MessageSquare size={20} /><div><h2>Le tue osservazioni</h2><p>Promesse, offerte, esperimenti: conserva il contesto insieme alla pagina.</p></div></div><textarea aria-label="Annotazioni sulla pagina" rows={3} placeholder="Scrivi cosa hai notato in questa landing…" value={notes} onChange={event => setNotes(event.target.value)} /><div><small>Le modifiche visibili aiutano a formulare ipotesi; non rivelano i risultati di conversione.</small><button className="button secondary compact" disabled={savingNotes || notes === (detail.notes || '')} onClick={async () => { setSavingNotes(true); await perform(() => api(`/api/pages/${page.id}`, { method: 'PATCH', body: JSON.stringify({ notes }) }), 'Annotazioni salvate.'); setSavingNotes(false); }}>{savingNotes ? <LoaderCircle size={15} className="spin" /> : <Check size={15} />} Salva note</button></div></section></>;
}

function CompareView({ versions }: { versions: Version[] }) {
  const [left, setLeft] = useState(versions[1]?.id || ''); const [right, setRight] = useState(versions[0]?.id || ''); const [tab, setTab] = useState<'visual' | 'text' | 'links'>('visual'); const [data, setData] = useState<Comparison | null>(null); const [error, setError] = useState('');
  useEffect(() => { if (!left || !right || left === right) { setData(null); return; } let cancelled = false; setData(null); setError(''); api<Comparison>(`/api/compare?left=${encodeURIComponent(left)}&right=${encodeURIComponent(right)}`).then(result => { if (!cancelled) setData(result); }).catch(error => { if (!cancelled) setError(error.message); }); return () => { cancelled = true; }; }, [left, right]);
  return <section className="panel compare-panel"><div className="compare-selection"><label>Versione di partenza<select value={left} onChange={event => setLeft(event.target.value)}>{versions.map(version => <option key={version.id} value={version.id}>{date(version.capturedAt)}</option>)}</select></label><ArrowRight size={22} /><label>Versione da confrontare<select value={right} onChange={event => setRight(event.target.value)}>{versions.map(version => <option key={version.id} value={version.id}>{date(version.capturedAt)}</option>)}</select></label></div><div className="compare-tabs"><div className="tabs"><button className={tab === 'visual' ? 'selected' : ''} onClick={() => setTab('visual')}><Monitor size={16} /> Aspetto</button><button className={tab === 'text' ? 'selected' : ''} onClick={() => setTab('text')}><FileText size={16} /> Testo</button><button className={tab === 'links' ? 'selected' : ''} onClick={() => setTab('links')}><Link2 size={16} /> Collegamenti</button></div>{tab === 'text' && <div className="diff-legend"><span className="removed">Rimosso</span><span className="added">Aggiunto</span></div>}</div>{left === right ? <Empty icon={<History size={26} />} title="Scegli due versioni diverse">Seleziona due date per osservare cosa è cambiato.</Empty> : error ? <div className="notice error">{error}</div> : !data ? <Spinner label="Preparazione del confronto" /> : tab === 'visual' ? <div className="visual-comparison">{[data.left, data.right].map((version, index) => <div key={`${version.id}-${index}`}><div className="compare-image-label"><span>{index ? 'Versione da confrontare' : 'Versione di partenza'}</span><strong>{date(version.capturedAt)}</strong></div><div className="compare-image"><a href={version.screenshotUrl} target="_blank" rel="noreferrer"><img src={version.screenshotUrl} alt={`Pagina acquisita il ${date(version.capturedAt)}`} /></a></div><a className="text-button" href={version.htmlUrl} download><ArrowDownToLine size={14} /> Scarica questa copia</a></div>)}</div> : tab === 'text' ? <div className="text-diff">{data.textDiff.some(part => part.added || part.removed) ? data.textDiff.map((part, index) => part.added ? <ins key={index}>{part.value}</ins> : part.removed ? <del key={index}>{part.value}</del> : <span key={index}>{part.value}</span>) : <div className="diff-unchanged"><Check size={21} /><strong>Nessuna differenza nel testo confrontato.</strong><p>Le versioni possono differire per immagini, collegamenti o altri elementi.</p></div>}</div> : <div className="link-comparison">{([{ title: 'Collegamenti rimossi', entries: data.changedLinks.removed, tone: 'removed' }, { title: 'Collegamenti aggiunti', entries: data.changedLinks.added, tone: 'added' }]).map(group => <div key={group.title}><h3 className={group.tone}>{group.title} <span>{group.entries.length}</span></h3>{group.entries.length ? group.entries.map((link, index) => <div className="changed-link" key={index}><strong>{link.text || 'Senza etichetta'}</strong><span>{link.url}</span></div>) : <p className="muted">Nessun collegamento.</p>}</div>)}</div>}</section>;
}

function Modal({ title, subtitle, close, children }: { title: string; subtitle?: string; close: () => void; children: ReactNode }) {
  const dialog = useRef<HTMLDivElement>(null); const closeRef = useRef(close); closeRef.current = close;
  useEffect(() => { const previous = document.activeElement as HTMLElement; const previousOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; const timer = setTimeout(() => dialog.current?.querySelector<HTMLElement>('input,button')?.focus(), 10); const keydown = (event: KeyboardEvent) => { if (event.key === 'Escape') closeRef.current(); if (event.key === 'Tab') { const controls = dialog.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]'); if (!controls?.length) return; const first = controls[0], last = controls[controls.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } } }; document.addEventListener('keydown', keydown); return () => { clearTimeout(timer); document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', keydown); previous?.focus(); }; }, []);
  return <div className="modal-overlay" onMouseDown={event => { if (event.target === event.currentTarget) close(); }}><div className="modal" ref={dialog} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-heading"><div><h2 id="modal-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={close} aria-label="Chiudi finestra"><X size={21} /></button></div>{children}</div></div>;
}

function SiteModal({ site, close, saved }: { site?: Site; close: () => void; saved: () => Promise<void> }) {
  const [name, setName] = useState(site?.name || ''); const [url, setUrl] = useState(site?.url || ''); const [kind, setKind] = useState(site?.kind || 'competitor'); const [intervalHours, setIntervalHours] = useState(site?.intervalHours || 6); const [maxPages, setMaxPages] = useState(site?.maxPages || 30); const [includeSubdomains, setIncludeSubdomains] = useState(site?.includeSubdomains || false); const [paused, setPaused] = useState(site?.paused || false); const [selectors, setSelectors] = useState((site?.ignoreSelectors || []).join('\n')); const [notes, setNotes] = useState(site?.notes || ''); const [advanced, setAdvanced] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { const body = { name: name.trim(), url: url.trim(), kind, intervalHours, maxPages, includeSubdomains, ignoreSelectors: selectors.split('\n').map(value => value.trim()).filter(Boolean), ...(site ? { paused, notes } : {}) }; await api(site ? `/api/sites/${site.id}` : '/api/sites', { method: site ? 'PATCH' : 'POST', body: JSON.stringify(body) }); await saved(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }
  return <Modal title={site ? 'Impostazioni del sito' : 'Aggiungi un sito'} subtitle={site ? 'Decidi come seguire la sua evoluzione.' : 'Un indirizzo oggi, una storia da consultare domani.'} close={() => { if (!busy) close(); }}><form onSubmit={submit}><div className="modal-body"><label>Nome del sito<input required maxLength={120} placeholder="Come vuoi chiamarlo nell’archivio" value={name} onChange={event => setName(event.target.value)} /></label><label>Indirizzo iniziale<input type="url" required disabled={!!site} placeholder="https://…" value={url} onChange={event => setUrl(event.target.value)} /><small>Puoi partire dal dominio o da una landing specifica.</small></label><fieldset className="kind-picker"><legend>Questo sito è</legend><label className={kind === 'own' ? 'selected' : ''}><input type="radio" name="site-kind" checked={kind === 'own'} onChange={() => setKind('own')} /><Globe2 size={18} /><span>Un mio sito</span></label><label className={kind === 'competitor' ? 'selected' : ''}><input type="radio" name="site-kind" checked={kind === 'competitor'} onChange={() => setKind('competitor')} /><Search size={18} /><span>Un competitor</span></label></fieldset><div className="form-columns"><label>Controlla le pagine ogni<div className="input-suffix"><input type="number" required min={1} max={8760} value={intervalHours} onChange={event => setIntervalHours(Number(event.target.value))} /><span>ore</span></div></label><label>Limite di pagine per sito<input type="number" required min={1} max={500} value={maxPages} onChange={event => setMaxPages(Number(event.target.value))} /></label></div><div className="form-info"><Clock3 size={18} /><span>Le pagine vengono controllate alla frequenza scelta. La ricerca di nuovi indirizzi viene ripetuta ogni giorno.</span></div><label className="checkbox-label"><input type="checkbox" checked={includeSubdomains} onChange={event => setIncludeSubdomains(event.target.checked)} /><span>Includi anche i sottodomini<small>Per trovare pagine pubbliche collegate su sottodomini dello stesso sito.</small></span></label>{site && <label className="checkbox-label"><input type="checkbox" checked={paused} onChange={event => setPaused(event.target.checked)} /><span>Metti in pausa il monitoraggio<small>Le copie già archiviate restano consultabili.</small></span></label>}<button type="button" className="advanced-toggle" onClick={() => setAdvanced(!advanced)}><Settings2 size={15} /> Opzioni avanzate <ChevronRight className={advanced ? 'rotate' : ''} size={15} /></button>{advanced && <div className="advanced-fields"><label>Elementi da ignorare nei confronti<textarea rows={3} placeholder="Un selettore CSS per riga" value={selectors} onChange={event => setSelectors(event.target.value)} /><small>Per esempio contatori o contenuti variabili. Gli elementi sono esclusi dal confronto e coperti nello screenshot; restano nella copia HTML.</small></label>{site && <label>Note sul sito<textarea rows={3} value={notes} onChange={event => setNotes(event.target.value)} /></label>}</div>}{error && <div className="notice error" role="alert">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>Annulla</button><button className="button primary" disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : site ? <Check size={17} /> : <Plus size={17} />}{site ? 'Salva impostazioni' : 'Aggiungi e acquisisci'}</button></div></form></Modal>;
}

function AddPageModal({ site, close, saved }: { site: Site; close: () => void; saved: () => Promise<void> }) {
  const [url, setUrl] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  return <Modal title="Aggiungi una pagina" subtitle={`La nuova pagina sarà associata a ${site.name}.`} close={() => { if (!busy) close(); }}><form onSubmit={async event => { event.preventDefault(); setBusy(true); setError(''); try { await post(`/api/sites/${site.id}/pages`, { url: url.trim() }); await saved(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }}><div className="modal-body"><label>Indirizzo della landing<input type="url" required placeholder="https://…" value={url} onChange={event => setUrl(event.target.value)} /><small>Incolla l’indirizzo completo trovato sul sito, in un annuncio o in una newsletter.</small></label>{error && <div className="notice error" role="alert">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>Annulla</button><button className="button primary" disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : <Plus size={17} />} Aggiungi pagina</button></div></form></Modal>;
}
